// JavaScript - Real-time Ballistic Computer for M4A1 SOPMOD
class BallisticComputer {
    constructor() {
        this.constants = {
            GRAVITY: 32.1738,        // ft/s²
            AIR_DENSITY: 0.0023769,   // slugs/ft³
            Projectile_BC: 0.168,     // G7 BC for M855
            Sight_Height: 1.5,        // inches above bore
            Barrel_Length: 14.5     // inches
        };

        this.corrections = {
            temperature: 0.0,         // °F deviation from 59°F
            pressure: 0.0,            // in/Hg deviation from 29.53
            humidity: 0.50            // relative humidity fraction
        };
    }

    calculateTrajectory(muzzleVelocity, angleDegrees, rangeYards) {
        const angleRad = angleDegrees * Math.PI / 180;
        const vx = muzzleVelocity * Math.cos(angleRad);
        const vy = muzzleVelocity * Math.sin(angleRad);

        let x = 0, y = this.constants.Sight_Height/12; // feet
        let t = 0;
        const dt = 0.0001;

        let trajectoryPoints = [];

        while (y >= 0 || t < 0.1) {
            trajectoryPoints.push({
                time: t,
                x_ft: x,
                y_ft: y,
                range_yd: x * 3,
                drop_in: y * 12,
                velocity_fps: Math.sqrt(vx*vx + vy*vy)
            });

            // Environmental corrections
            const airDensityCorrected = this.applyEnvironmentalCorrections();

            // Drag calculation
            const dragCoeff = this.calculateDrag(vx, vy, airDensityCorrected);

            // Accelerations
            const ax = -dragCoeff * vx / this.constants.Projectile_BC;
            const ay = -this.constants.GRAVITY - (dragCoeff * vy / this.constants.Projectile_BC);

            // Update state
            vx += ax * dt;
            vy += ay * dt;
            x += vx * dt;
            y += vy * dt;
            t += dt;

            if (t > 15) break; // Safety limit
        }

        return this.interpolateToRange(trajectoryPoints, rangeYards);
    }

    applyEnvironmentalCorrections() {
        // Density altitude calculation
        const tempFactor = (this.corrections.temperature - 59) * -0.0035;
        const pressureFactor = (this.corrections.pressure - 29.53) * 0.001389;
        const humidityFactor = this.corrections.humidity * 0.000693;

        return this.constants.AIR_DENSITY * 
               Math.exp(tempFactor) * 
               Math.exp(pressureFactor) * 
               Math.exp(humidityFactor);
    }

    calculateDrag(vx, vy, airDensity) {
        const velocityMag = Math.sqrt(vx*vx + vy*vy);
        if (velocityMag === 0) return 0;

        // Mach number calculation
        const mach = velocityMag / 1125; // speed of sound in ft/s
        const dragCoefficient = this.getDragCoefficient(mach);

        return 0.5 * airDensity * velocityMag * velocityMag * dragCoefficient;
    }

    getDragCoefficient(mach) {
        // Supersonic drag model for 62gr projectile
        if (mach >= 1.0) {
            return 0.295 - (mach - 1.0) * 0.045;
        } else {
            return 0.42 + (1.0 - mach) * 0.18;
        }
    }
}

