// GPIO interrupt handler structure
typedef struct {
    gpio_isr_t fn;      // Function pointer to ISR
    void* arg;          // Argument to pass to ISR
    uint32_t mode;      // Interrupt mode (rising/falling/both)
} gpio_isr_entry_t;

// Install GPIO ISR service
esp_err_t gpio_install_isr_service(int intr_alloc_flags) {
    // Allocate memory for ISR handlers array
    gpio_isr_entry = heap_caps_calloc(GPIO_PIN_COUNT, sizeof(gpio_isr_entry_t), MALLOC_CAP_32BIT);

    // Configure CPU interrupt
    esp_err_t ret = esp_intr_alloc(GPIO_INTR_SOURCE, intr_alloc_flags, 
                                   gpio_isr_handler_add, NULL, &gpio_isr_handle);
    return ret;
}

// Register specific GPIO interrupt
esp_err_t gpio_isr_handler_add(gpio_num_t gpio_num, gpio_isr_t isr_handler, void* args) {
    // Validate GPIO number
    if (gpio_num >= GPIO_NUM_MAX || gpio_num < 0) {
        return ESP_ERR_INVALID_ARG;
    }

    // Configure interrupt type
    uint32_t intr_type;
    switch (gpio_ll_get_pin_input_enable(&GPIO, gpio_num)) {
        case GPIO_INTR_POSEDGE:
            intr_type = 0x02;
            break;
        case GPIO_INTR_NEGEDGE:
            intr_type = 0x01;
            break;
        case GPIO_INTR_ANYEDGE:
            intr_type = 0x03;
            break;
    }

    // Enable interrupt in register
    GPIO_PIN_PIN_REG(gpio_num) |= (intr_type << 9);

    // Store handler
    gpio_isr_entry[gpio_num].fn = isr_handler;
    gpio_isr_entry[gpio_num].arg = args;

    return ESP_OK;
}
```

