// lldesc_s — DMA link descriptor (8 words, 32 bytes each)
typedef struct {
    uint32_t eof:      1;   // Bit[0]   — End of frame flag
    uint32_t owner:    1;   // Bit[1]   — 0=CPU, 1=DMA
    uint32_t data_len: 16;  // Bits[2:17] — Payload byte count (max 4092)
    uint32_t buf_len:  14;  // Bits[18:31] — DMA buffer length (must be word-aligned)
    uint32_t buf_addr;      // Word[1]  — Physical SRAM address of buffer
    uint32_t next_desc;     // Word[2]  — Pointer to next lldesc_s (or 0 for last)
    uint32_t reserved[2];   // Words[3-4] — Reserved
