## 4. Double-Buffer Interrupt Handler & FFT Pipeline

```c
#include "esp_dsp.h"
#include "dsps_fft4r.h"

// DSP library requires 16-byte aligned buffers for SIMD optimization
static DRAM_ATTR float   fft_input[FFT_SIZE]  __attribute__((aligned(16)));
static DRAM_ATTR float   fft_output[FFT_SIZE] __attribute__((aligned(16)));
static DRAM_ATTR float   fft_window[FFT_SIZE] __attribute__((aligned(16)));
static DRAM_ATTR float   psd_db[FFT_SIZE/2]   __attribute__((aligned(16)));

static uint8_t   dma_buf_a[SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE] __attribute__((aligned(16)));
static uint8_t   dma_buf_b[SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE] __attribute__((aligned(16)));
static volatile uint8_t active_buffer = 0;  // 0 = A filling, 1 = B filling

// Cooley-Tukey FFT configuration
#define FFT_SIZE         1024
#define SAMPLE_RATE_HZ   16000
#define FREQ_RES_HZ      (SAMPLE_RATE_HZ / FFT_SIZE)   // 15.625 Hz/bin
#define PEAK_THRESHOLD_DB (-40.0f)                       // -40 dBFS noise floor

// Precompute Hann window coefficients
static void hann_window_init(void) {
    for (int i = 0; i < FFT_SIZE; i++) {
        fft_window[i] = 0.5f * (1.0f - cosf(2.0f * M_PI * i / (FFT_SIZE - 1)));
    }
}

// ISR — executed in IRAM, minimal overhead, no floating point
static IRAM_ATTR void i2s_dma_isr(void *arg) {
    // Clear DMA out-of-band interrupt
    I2S0.int_clr.rx_eof = 1;

    BaseType_t higher_priority_task_woken = pdFALSE;

    // Signal audio processing task from ISR (no float, no malloc)
    vTaskNotifyGiveFromISR(processing_task_handle, &higher_priority_task_woken);

    if (higher_priority_task_woken) {
        portYIELD_FROM_ISR();
    }
}

// Audio processing task — runs at core-pinned priority
void audio_processing_task(void *params) {
    hann_window_init();
    dsps_fft4r_init();  // Initialize radix-4 FFT lookup tables in RAM

    while (1) {
        // Block until DMA EOF interrupt fires
        ulTaskNotifyTake(pdTRUE, portMAX_DELAY);

        // Determine which buffer just completed (ping-pong read of filled buffer)
        uint8_t completed_buf = active_buffer ^ 1;  // XOR toggles 0↔1
        active_buffer ^= 1;

        // Extract int16 PCM from 32-bit I²S word (LSW) + apply DC offset removal
        int32_t *raw_i2s = (int32_t *)(completed_buf == 0 ? dma_buf_a : dma_buf_b);
        float   dc_bias = 0.0f;

        // First pass: compute DC bias (mean)
        for (int i = 0; i < FFT_SIZE; i++) {
            dc_bias += (float)(raw_i2s[i] & 0xFFFF);  // Lower 16-bit PCM sample
        }
        dc_bias /= FFT_SIZE;

        // Second pass: window + de-DC + cast to float (Q15 → normalized)
        for (int i = 0; i < FFT_SIZE; i++) {
            int16_t sample = (int16_t)(raw_i2s[i] & 0xFFFF);
            fft_input[i] = fft_window[i] * ((float)sample / 32768.0f - dc_bias);
        }

        // Radix-4 FFT (O(N log₄ N) — 256 iterations for N=1024)
        dsps_fft4r_fc(fft_input, FFT_SIZE);

        // Complex-to-magnitude-squared (strip chart)
        for (int i = 0; i < FFT_SIZE / 2; i++) {
            float re = fft_input[i * 2];
            float im = fft_input[i * 2 + 1];
            float mag_sq = re * re + im * im;

            // Compute two-sided PSD: P = (|X|² × 2) / (fs × N²)  [watts/Hz, linear]
            float psd_linear = (2.0f * mag_sq) / ((float)SAMPLE_RATE_HZ * (float)(FFT_SIZE * FFT_SIZE));
            psd_db[i] = 10.0f * log10f(psd_linear + 1e-12f);  // +1e-12 prevents log(0)
        }

        // Peak detection (bins 0..512, corresponding to 0..8kHz)
        float max_magnitude_db = -120.0f;
        int   peak_bin = 0;
        for (int i = 1; i < FFT_SIZE / 2; i++) {
            if (psd_db[i] > max_magnitude_db) {
                max_magnitude_db = psd_db[i];
                peak_bin = i;
            }
        }

        if (max_magnitude_db > PEAK_THRESHOLD_DB) {
            float peak_freq = peak_bin * FREQ_RES_HZ;
            // Log to UART (115200 baud, ~1ms per 10-char log line)
            ets_printf("PEAK: freq=%.1fHz  bin=%d  mag=%.2fdBFS\n",
                        peak_freq, peak_bin, max_magnitude_db);
        }

        // Memory barrier before next DMA cycle
        __asm__ volatile ("memw" ::: "memory");
    }
}

// Main entry
void app_main(void) {
    static lldesc_s dma_desc[2] __attribute__((aligned(16)));

    i2s_gpio_init();
    i2s_hw_init();
    i2s_dma_link_init(dma_desc, dma_buf_a, dma_buf_b);

    // Register DMA completion ISR
    ESP_ERROR_CHECK(i2s_isr_handle_register(i2s_dma_isr, NULL, ESP_INTR_FLAG_SHARED | ESP_INTR_FLAG_IRAM));
    I2S0.int_ena.rx_eof = 1;  // Enable DMA EOF interrupt

    xTaskCreatePinnedToCore(audio_processing_task, "audio_fft",
                            8192, NULL, 5, &processing_task_handle, 1);
}
