#### **IV.1 Core Control Task (Core 0)**

```cpp
// gazebo_controller.cpp - Task 1 (Core 0)
void gazebo_adaptive_task(void* param) {
    const TickType_t xDelay = pdMS_TO_TICKS(1);  // 1ms period

    while(1) {
        // Load compensated IMU data
        sensor_frame_t current = get_latest_sensor_frame();

        // Compute angular acceleration using central difference
        float dt = 0.001f;  // Fixed timestep
        float alpha_roll = (current.gyro_x - prev.gyro_x) / dt;

        // Update disturbance observer
        update_disturbance_estimate(&current);

        // Apply anti-individual-disturbance filter
        float filtered_error[3] = {0};
        apply_individual_disturbance_filter(current.error, filtered_error);

        // Compute control outputs
        float motor_commands[4];
        compute_motor_outputs(filtered_error, motor_commands);

        // Send to ESCs via LEDC
        send_to_escs(motor_commands);

        prev = current;
        vTaskDelayUntil(&last_wake_time, xDelay);
    }
}
