#### **IV.2 Individual Disturbance Filter (Median of Three)**

```cpp
void apply_individual_disturbance_filter(float error_in[3], float error_out[3]) {
    static float error_history[3][3][5];  // [axis][sample][history]
    static uint8_t history_ptr = 0;

    for(int axis = 0; axis < 3; axis++) {
        // Shift history buffer
        memmove(&error_history[axis][1], &error_history[axis][0], 4 * sizeof(float));
        error_history[axis][0] = error_in[axis];

        // Median-of-three selection
        float med = median_of_three(error_history[axis][0], 
                                    error_history[axis][1], 
                                    error_history[axis][2]);
        error_out[axis] = med;
    }
    history_ptr = (history_ptr + 1) % 5;
}

inline float median_of_three(float a, float b, float c) {
    if((a <= b) && (b <= c)) return b;
    if((c <= b) && (b <= a)) return b;
    if((a <= c) && (c <= b)) return c;
    if((b <= c) && (c <= a)) return c;
    return a;
}
```

