#define Q15_MULT(a, b) (((int32_t)(a) * (int32_t)(b)) >> 15)
#define FLOAT_TO_Q15(f) ((int16_t)((f) * 32768.0f))
#define Q15_TO_FLOAT(q) ((float)(q) / 32768.0f)

// Example: Fast exponential for disturbance decay
int16_t fast_exp_q15(int16_t x_q15) {
    int16_t x_abs = abs(x_q15);
    if(x_abs > 16384) return (x_q15 > 0) ? 32767 : -32768;

    int32_t result = 16384 + (x_q15 >> 1) + (Q15_MULT(x_q15, x_q15) >> 2);
    return (int16_t)result;
}
